Why does this return 4.0 for everything above 80?

def to_gpa(score):
    if score >= 80:
        return 4.0
    elif score >= 70:
        return 3.0
    elif score >= 60:
        return 2.0
    return 0.0

print(to_gpa(85), to_gpa(72), to_gpa(55))
